function recordEvent(a,label){a.records.push({label,at:Date.now()});opsLog.push({event:a.id,label,at:Date.now()})}
function acknowledgeEvent(a){if(a.resolved||a.ack)return;a.ack=true;recordEvent(a,'值班人员已确认（模拟）');refreshOps(a)}
function handleEvent(a){if(a.resolved||!a.ack||a.handled)return;a.handled=true;recordEvent(a,a.id==='heat'?'已记录通风与空调排查（模拟）':'已记录网络与供电排查（模拟）');refreshOps(a)}
function recoverEvent(a){if(a.resolved||!a.handled)return;a.resolved=true;if(a.id==='heat'){hotRoom.temp=24.8;a.history.push(28.3,26.1,24.8)}else {badCamera.online=true;a.history.push(1,1,1)}recordEvent(a,a.id==='heat'?'复测 24.8°C，规则校验通过':'连续 3 次心跳正常，规则校验通过');recordEvent(a,'事件已关闭（模拟）');highlight.material.color.set(0x72eac9);beacon.visible=false;refreshOps(a)}
function refreshOps(a){if(currentAlert?.id===a.id||selected===a.bi)renderDetail();updateOverview()}
function trendSvg(a){let values=a.history,min=a.id==='heat'?20:0,max=a.id==='heat'?36:1.2;const points=values.map((v,i)=>`${8+i/(values.length-1)*324},${76-(v-min)/(max-min)*64}`).join(' '),threshold=76-(30-20)/16*64;return `<svg class="ops-chart" viewBox="0 0 340 92" role="img" aria-label="${a.id==='heat'?'模拟温度采样趋势':'模拟设备心跳趋势'}"><defs><linearGradient id="opsfill" x2="0" y2="1"><stop stop-color="#a3e4ca" stop-opacity=".2"/><stop offset="1" stop-color="#a3e4ca" stop-opacity="0"/></linearGradient></defs><path d="M8 76H332M8 44H332M8 12H332" stroke="#b4d4ce15" fill="none"/>${a.id==='heat'?`<path d="M8 ${threshold}H332" stroke="#e5bd7b88" stroke-dasharray="4 4"/><text x="286" y="${threshold-5}" fill="#c4ac85" font-size="8">30°C 阈值</text>`:''}<polygon points="8,78 ${points} 332,78" fill="url(#opsfill)"/><polyline points="${points}" fill="none" stroke="${a.resolved?'#9ee3c5':'#e8c58d'}" stroke-width="2"/><text x="8" y="90" fill="#94b4bf" font-size="8">${a.id==='heat'?'每 2 分钟采样':'每次心跳检测'} · 模拟序列</text><text x="307" y="90" fill="#94b4bf" font-size="8">最近</text></svg>`}
function renderAlerts(){const a=currentAlert||alerts.find(x=>x.bi===selected);if(!a)return '<div class="empty-state">✓ 当前建筑暂无演示告警</div>';const x=rooms.find(r=>r.id===a.room),dev=equipment.find(d=>d.id===a.device);return `<div class="ops-header"><span class="state-chip ${a.resolved?'':'warning'}">${a.resolved?'已恢复':a.handled?'待复测':a.ack?'已确认':'待确认'}</span><span>◇ 模拟规则分析</span></div><div class="ops-primary"><div><h3>${a.title}</h3><p>${data[a.bi][0]} · ${x.name}</p></div><strong class="${a.resolved?'good-text':''}">${a.resolved?(a.id==='heat'?'24.8°C':'心跳正常'):a.id==='heat'?'32.6°C':'离线'}</strong></div><div class="ops-section"><div class="subheading">${a.id==='heat'?'温度变化趋势':'设备心跳趋势'}<small>${a.resolved?'复测已通过':'异常采样记录'}</small></div>${trendSvg(a)}</div><div class="impact-grid"><div><b>1</b><span>${a.resolved?(a.id==='heat'?'原影响教室':'原影响阅览室'):(a.id==='heat'?'受影响教室':'受影响阅览室')}</span></div><div><b>${a.id==='heat'?'3':'1'}</b><span>${a.id==='heat'?'关联设备':a.resolved?'已恢复画面':'不可用画面'}</span></div><div><b>${a.id==='heat'?(x.occupied?'使用中':'空闲'):'门禁正常'}</b><span>${a.id==='heat'?'房间状态':'关联门禁状态'}</span></div></div><div class="rule-note"><b>${a.resolved?'历史触发依据':'规则依据'}</b><p>${a.id==='heat'?'连续 3 次以上采样高于 30°C：30.2 → 31.1 → 31.8 → 32.6°C。':'连续 3 次以上心跳未到达，且目标设备在线标记为离线。'}</p><small>用于讲解的确定性规则，非真实 AI 诊断。</small></div><div class="intelligence-note">◇ 建议处置 <span>${a.id==='heat'?'核查传感器 → 检查通风及空调 → 复测温度 → 关闭事件。':'检查供电与网络 → 确认设备恢复 → 验证连续心跳 → 关闭事件。'}</span></div><div class="alarm-link">${dev.name} · ${dev.serial}<small>场景点位为楼栋级示意，未建立室内精确模型</small></div><div class="subheading">处置时间线 <small>本次模拟会话</small></div><ol class="event-timeline">${a.records.map((r,i)=>`<li class="${i===a.records.length-1?'latest':''}"><i></i><span>${r.label}</span><time>${new Date(r.at).toLocaleTimeString('zh-CN',{hour12:false})}</time></li>`).join('')}</ol><div class="alarm-actions"><button data-open-alert="${a.id}">定位</button>${!a.resolved?`<button id="ackAlert" ${a.ack?'disabled':''}>${a.ack?'已确认':'确认告警'}</button><button id="handleAlert" ${!a.ack||a.handled?'disabled':''}>${a.handled?'已排查':'模拟排查'}</button><button id="recoverAlert" ${!a.handled?'disabled':''}>复测并恢复</button>`:'<span class="closed-note">✓ 处置闭环已完成</span>'}</div>`}
function resetSimulation(){equipment.forEach(d=>Object.assign(d,initialEquipment.find(x=>x.id===d.id)));hotRoom.temp=32.6;alerts.forEach(a=>{a.ack=false;a.handled=false;a.resolved=false;a.history=a.id==='heat'?[24.8,25.1,26.2,27.4,28.7,30.2,31.1,31.8,32.6]:[1,1,1,1,0,0,0,0,0];a.records=[{label:'规则检测到异常',at:Date.now()-120000},{label:'已关联建筑、房间与设备',at:Date.now()-115000}]});opsLog.length=0;updateOverview();$('#reset').click()}

function updateOverview(){const online=equipment.filter(d=>d.online).length,used=rooms.filter(r=>r.occupied).length,pending=alerts.filter(a=>!a.resolved);$('.online-stat b').innerHTML=(online/equipment.length*100).toFixed(1)+'<small>%</small>';$('.ring b').innerHTML=Math.round(used/rooms.length*100)+'<small>%</small>';$('.count').textContent=pending.length+' 项待关注';$('.scene-status').innerHTML=`<i></i> 校园整体运行 <span>${pending.length?pending.length+' 项异常待关注':'当前无待处理告警'}</span>`;$('#deviceRows').innerHTML=[['light','☼','智慧照明','LIGHTING'],['camera','◉','视频监控','CAMERA'],['access','⌑','门禁系统','ACCESS'],['sensor','❖','环境传感器','SENSOR']].map(([type,icon,name,en])=>{let ds=equipment.filter(d=>d.type===type),on=ds.filter(d=>d.online).length;return `<button class="device device-summary" data-kind="${type}"><span>${icon}</span><div><b>${name}</b><small>${en}</small></div><label><strong>${on} 在线</strong><small>${ds.length-on} 离线 · ${ds.filter(d=>d.online&&d.running).length} ${type==='access'?'解锁':type==='light'?'开启':'运行'}</small></label></button>`}).join('');document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{const ds=equipment.filter(d=>d.type===b.dataset.kind),d=ds.find(x=>!x.online)||ds[0];openBuilding(d.bi,'devices');if(d.room)currentRoom=rooms.find(r=>r.id===d.room);deviceFilter=d.online?'all':'offline';focusBuilding(d.bi,d.id);renderDetail()});$('.events-panel').querySelectorAll('.alert').forEach((b,i)=>{const a=alerts[i];b.classList.toggle('resolved',a.resolved);b.querySelector('.alert-type').childNodes[0].textContent=a.resolved?'✓ 已恢复 ':a.title+' ';b.querySelector('time').textContent=a.resolved?'本次会话':a.ack?'已确认':i?'2 分钟前':'刚刚';if(a.resolved)b.querySelector('small').innerHTML='状态已恢复正常<span class="locate">查看 ↗</span>';else if(i===1)b.querySelector('small').innerHTML='连接中断 · 待检查网络<span class="locate">定位 ↗</span>';else if(i===0)b.querySelector('small').innerHTML='<strong>32.6<sub>°C</sub></strong><span class="alert-desc">超出阈值 2.6°C</span><span class="locate">定位 ↗</span>'});labels[0].el.classList.toggle('warn',!alerts[0].resolved);labels[0].el.textContent=(!alerts[0].resolved?'◉ ':'')+data[0][0];const badge=$('#buildings button small');badge.textContent=alerts[0].resolved?'查看 →':'● 预警'}
$('#buildings').innerHTML=data.map((r,i)=>`<button data-id="${i}"><span>▧</span>${r[0]}<small>${i===0?'● 预警':'查看 →'}</small></button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openBuilding(+b.dataset.id));document.querySelectorAll('[data-focus]').forEach((b,i)=>b.onclick=()=>openAlert(alerts[i].id));
$('#reset').onclick=()=>{document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='overview'));document.body.dataset.view='overview';$('.left').scrollTop=0;$('.right').scrollTop=0;desiredTarget.set(0,0,0);desiredRadius=285;angle=.72;elevation=.83;$('#detail').hidden=true;marker.visible=false;highlight.visible=false;beacon.visible=false;selected=-1;document.querySelectorAll('#buildings button').forEach(b=>b.classList.remove('selected'))};$('#rotate').onclick=()=>{auto=!auto;$('#rotate').classList.toggle('on',auto);toast(auto?'已开始校园自动巡航':'已暂停自动巡航')};$('#alarm').onclick=()=>{if(alerts[0].resolved)resetSimulation();openAlert('heat')};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('当前环境不支持全屏'))};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.body.dataset.view=b.dataset.tab;if(b.dataset.tab==='devices'){openBuilding(0,'devices')}else if(b.dataset.tab==='energy'){$('.energy-panel').scrollIntoView({behavior:'smooth',block:'start'});toast('当前展示今日模拟用电趋势')}else $('#reset').click()});updateOverview();
// Guided customer walkthroughs. All actions operate on the same disposable simulation state.
const tour={scenario:'daily',index:-1,playing:false,mode:'ready',timer:null};
const walkthroughs={
 daily:{name:'校园日常运行',steps:[
 ['全域总览','从校园全景观察 8 栋建筑、128 间房间与 386 台模拟设备的运行概况。',()=>{$('#reset').click();auto=true;$('#rotate').classList.add('on')}],
 ['空间使用','97 间使用中、31 间空闲。进入教学楼，查看房间使用状态与课程信息。',()=>{openBuilding(0);currentRoom=rooms.find(r=>r.id==='B0-302');renderDetail()}],
 ['环境感知','温度、湿度、AQI 与 PM2.5 随房间切换；环境值与该房间的关联设备一起呈现。',()=>{openBuilding(1);renderDetail()}],
 ['设备态势','在线与运行是两个不同状态。照明和门禁支持会话内模拟控制，离线设备禁止下发。',()=>{openBuilding(1,'devices')}],
 ['运营价值','用空间串联房间、设备和事件。演示完成，可切换异常处置脚本或手动探索。',()=>{$('#reset').click()}]
 ]},
 heat:{name:'环境异常处置',steps:[
 ['发现异常','教学楼 A 的 301 教室触发温度告警，镜头定位并高亮楼栋及传感器示意点。',()=>openAlert('heat')],
 ['规则研判','连续多次采样高于 30°C。趋势、阈值与样本共同解释告警来源，非真实 AI 诊断。',()=>{openAlert('heat');$('.detail-content').scrollTop=0}],
 ['查看影响','异常关联 1 间使用中教室与 3 台房间设备，可进一步核查环境和设备状态。',()=>{openAlert('heat');detailTab='rooms';renderDetail()}],
 ['确认事件','模拟值班人员确认告警。事件保留，直到完成排查与复测，不会直接消失。',()=>{openAlert('heat');acknowledgeEvent(alerts[0])}],
 ['记录排查','按规则建议记录通风和空调检查。本演示只记录模拟排查，不控制真实设备。',()=>{openAlert('heat');handleEvent(alerts[0]);$('.detail-content').scrollTop=9999}],
 ['复测闭环','模拟复测降至 24.8°C，更新房间温度、待处理数量和时间线，关闭该事件。',()=>{openAlert('heat');recoverEvent(alerts[0]);$('.detail-content').scrollTop=9999}]
 ]},
 camera:{name:'设备离线排查',steps:[
 ['离线告警','图书馆 201 阅览室摄像头心跳丢失，系统关联建筑、房间与设备编号。',()=>openAlert('camera')],
 ['核查设备','切换到目标房间的离线设备，显示设备身份、连接状态与楼栋示意点位。',()=>{openAlert('camera');detailTab='devices';deviceFilter='offline';renderDetail()}],
 ['确认影响','1 路模拟画面不可用；门禁仍在线锁定。确认事件后，按建议检查网络与供电。',()=>{openAlert('camera');acknowledgeEvent(alerts[1])}],
 ['模拟排查','记录供电和网络排查过程。状态仍待复测，避免把排查操作直接当成设备恢复。',()=>{openAlert('camera');handleEvent(alerts[1]);$('.detail-content').scrollTop=9999}],
 ['验证恢复','连续 3 次模拟心跳通过，在线率由 98.4% 更新至 98.7%，并保留处置记录。',()=>{openAlert('camera');recoverEvent(alerts[1]);$('.detail-content').scrollTop=9999}]
 ]}
};
const tourPanel=document.createElement('section');tourPanel.id='tourPanel';tourPanel.hidden=true;document.body.append(tourPanel);
const tourButton=document.createElement('button');tourButton.id='tourLauncher';tourButton.textContent='▷ 一键讲解';$('.tools').prepend(tourButton);
function clearTourTimer(){clearTimeout(tour.timer);tour.timer=null}
function drawTour(){document.body.dataset.tourMode=tour.mode;const script=walkthroughs[tour.scenario],step=script.steps[Math.max(tour.index,0)];tourPanel.innerHTML=`<div class="tour-top"><div><span class="tour-icon">◇</span><b>客户讲解</b><small>${{ready:'准备就绪',playing:'自动讲解中',paused:'已暂停',manual:'已手动接管',complete:'讲解完成'}[tour.mode]}</small></div><button id="exitTour" aria-label="关闭讲解">×</button></div><div class="tour-select-row"><label>场景<select id="tourScenario" aria-label="演示场景">${Object.entries(walkthroughs).map(([id,s])=>`<option value="${id}" ${tour.scenario===id?'selected':''}>${s.name}</option>`).join('')}</select></label><span>全流程为模拟操作</span></div>${tour.index>=0?`<div class="tour-copy" aria-live="polite"><div><span>${String(tour.index+1).padStart(2,'0')} / ${script.steps.length}</span><b>${step[0]}</b></div><p>${step[1]}</p></div><div class="tour-progress">${script.steps.map((s,i)=>`<button data-step="${i}" class="${i===tour.index?'active':i<tour.index?'done':''}" aria-label="跳至步骤 ${i+1}：${s[0]}" title="${s[0]}"></button>`).join('')}</div>`:'<p class="tour-intro">自动切换镜头、空间与业务状态，按步骤讲清校园管理价值。操作界面即可暂停并接管。</p>'}<div class="tour-actions">${tour.index<0?'<button id="startTour" class="primary">开始讲解</button>':`<button id="previousTour" ${tour.index<=0?'disabled':''}>上一步</button><button id="playTour" class="primary">${tour.mode==='complete'?'重新播放':tour.playing?'暂停':'继续讲解'}</button><button id="nextTour" ${tour.index>=script.steps.length-1?'disabled':''}>下一步</button><button id="takeoverTour">手动接管</button>`}<button id="resetTour">重置演示</button></div>`;
 $('#exitTour').onclick=closeTour;$('#tourScenario').onchange=e=>{clearTourTimer();tour.scenario=e.target.value;tour.index=-1;tour.playing=false;tour.mode='ready';resetSimulation();drawTour()};if($('#startTour'))$('#startTour').onclick=startTour;if($('#previousTour'))$('#previousTour').onclick=()=>goTourStep(tour.index-1);if($('#nextTour'))$('#nextTour').onclick=()=>goTourStep(tour.index+1);if($('#playTour'))$('#playTour').onclick=()=>{if(tour.mode==='complete')startTour();else if(tour.playing)pauseTour('paused');else {if(tour.mode==='manual')walkthroughs[tour.scenario].steps[tour.index][2]();tour.playing=true;tour.mode='playing';drawTour();scheduleTour()}};if($('#takeoverTour'))$('#takeoverTour').onclick=()=>pauseTour('manual');$('#resetTour').onclick=()=>{clearTourTimer();tour.index=-1;tour.playing=false;tour.mode='ready';resetSimulation();drawTour();toast('模拟数据与视角已重置')};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>goTourStep(+b.dataset.step));
}
function scheduleTour(){clearTourTimer();if(!tour.playing)return;tour.timer=setTimeout(()=>{const max=walkthroughs[tour.scenario].steps.length-1;if(tour.index<max)goTourStep(tour.index+1);else {tour.playing=false;tour.mode='complete';auto=false;drawTour()}},tour.index===walkthroughs[tour.scenario].steps.length-1?8000:9500)}
function goTourStep(n){const steps=walkthroughs[tour.scenario].steps;if(n<0||n>=steps.length)return;clearTourTimer();if(n<=tour.index){resetSimulation();for(let i=0;i<n;i++)steps[i][2]()}else{for(let i=tour.index+1;i<n;i++)steps[i][2]()}tour.index=n;steps[n][2]();drawTour();scheduleTour()}
function startTour(){clearTourTimer();resetSimulation();tour.index=-1;tour.playing=true;tour.mode='playing';goTourStep(0)}
function pauseTour(mode){clearTourTimer();tour.playing=false;tour.mode=mode;auto=false;$('#rotate').classList.remove('on');drawTour()}
function closeTour(){clearTourTimer();tour.playing=false;auto=false;tourPanel.hidden=true;document.body.classList.remove('touring');$('#rotate').classList.remove('on')}
tourButton.onclick=()=>{tourPanel.hidden=false;document.body.classList.add('touring');drawTour()};
document.addEventListener('pointerdown',e=>{if(tour.playing&&e.isTrusted&&!e.target.closest('#tourPanel')&&!e.target.closest('#tourLauncher'))pauseTour('manual')},true);
document.addEventListener('keydown',e=>{if(tour.playing&&e.isTrusted&&!e.target.closest('#tourPanel'))pauseTour('manual')},true);

let down=false,moved=false,last={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>{down=true;moved=false;last={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;angle-=dx*.006;elevation=T.MathUtils.clamp(elevation+dy*.004,.25,1.35);last={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{down=false;if(moved)return;let p=new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),ray=new T.Raycaster();ray.setFromCamera(p,camera);let hit=ray.intersectObjects(buildings,true)[0];if(hit)select(hit.object.userData.id)});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();desiredRadius=T.MathUtils.clamp(desiredRadius+e.deltaY*.15,110,460)},{passive:false});renderer.domElement.style.touchAction='none';window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});function clock(){$('#clock').textContent=new Date().toLocaleString('zh-CN',{hour12:false})}clock();setInterval(clock,1000);setInterval(()=>$('#temp').innerHTML=(24.8+(Math.random()-.5)*.4).toFixed(1)+'<small>°C</small>',6000);function animate(t){requestAnimationFrame(animate);if(auto)angle+=.0012;target.lerp(desiredTarget,.045);radius+=(desiredRadius-radius)*.045;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*radius,target.y+Math.sin(elevation)*radius,target.z+Math.cos(angle)*Math.cos(elevation)*radius);camera.lookAt(target);marker.material.opacity=.5+Math.sin(t*.003)*.3;beacon.scale.setScalar(1+Math.sin(t*.003)*.18);camera.updateMatrixWorld();labels.forEach(({el,p},i)=>{let q=p.clone().project(camera);el.style.left=(q.x*.5+.5)*innerWidth+'px';el.style.top=(-q.y*.5+.5)*innerHeight+'px';el.style.display=q.z>1||q.x<-1||q.x>1||(![0,2,4].includes(i)&&i!==selected)?'none':'block'});renderer.render(scene,camera)}animate(0);
